func ptrTurn(p unsafe.Pointer, c int32) any {
	r := (*shipmentimportchat.Turn)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.ConversationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 4:
		return (*string)(unsafe.Pointer(&r.DocumentID))
	case 5:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 6:
		return (*int64)(unsafe.Pointer(&r.TurnIndex))
	case 7:
		return &r.UserMessage
	case 8:
		return &r.AssistantMessage
	case 9:
		return &r.RequestConversationID
	case 10:
		return &r.ResponseConversationID
	case 11:
		return &r.Model
	case 12:
		return (*string)(unsafe.Pointer(&r.ResultStatus))
	case 13:
		return &r.ErrorMessage
	case 14:
		return &r.ContextJSON
	case 15:
		return &r.SuggestionsJSON
	case 16:
		return &r.ToolCallsJSON
	case 17:
		return &r.ActionsJSON
	case 18:
		return &r.CreatedAt
	}
	return nil
}

func valueTurn(p unsafe.Pointer, c int32) any {
	r := (*shipmentimportchat.Turn)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.ConversationID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.BusinessUnitID)
	case 4:
		return string(r.DocumentID)
	case 5:
		return string(r.UserID)
	case 6:
		return int64(r.TurnIndex)
	case 7:
		return r.UserMessage
	case 8:
		return r.AssistantMessage
	case 9:
		if r.RequestConversationID == "" {
			return nil
		}
		return r.RequestConversationID
	case 10:
		if r.ResponseConversationID == "" {
			return nil
		}
		return r.ResponseConversationID
	case 11:
		if r.Model == "" {
			return nil
		}
		return r.Model
	case 12:
		return string(r.ResultStatus)
	case 13:
		if r.ErrorMessage == "" {
			return nil
		}
		return r.ErrorMessage
	case 14:
		if r.ContextJSON == nil {
			return keel.EmptyJSONArray
		}
		return r.ContextJSON
	case 15:
		if r.SuggestionsJSON == nil {
			return keel.EmptyJSONArray
		}
		return r.SuggestionsJSON
	case 16:
		if r.ToolCallsJSON == nil {
			return keel.EmptyJSONArray
		}
		return r.ToolCallsJSON
	case 17:
		if r.ActionsJSON == nil {
			return keel.EmptyJSONArray
		}
		return r.ActionsJSON
	case 18:
		return r.CreatedAt
	}
	return nil
}

